import "server-only";
import { cookies } from "next/headers";
import index from "@/data/fitment-index.json";
import { COOKIE } from "@/lib/personas";

// App-side fitment (DEV_GUIDE §8). The index is generated by the seeder and bundled with the build;
// re-deploy after re-seeding. Only this server module reads the full index; the client gets the
// small selector tree (vehicleTree) and server-rendered results.

interface FitmentIndex {
  vehicles: Record<string, { make: string; model: string; years: [number, number]; type?: string }>;
  makes: Record<string, string[]>;
  byVehicleYear: Record<string, string[]>;
  byProduct: Record<string, string[]>;
  universal: string[];
}
const IDX = index as unknown as FitmentIndex;
const UNIVERSAL = new Set(IDX.universal);

/** A garage entry: a vehicle application key plus a model year (no PII). Serialized as "KEY|YEAR". */
export interface Vehicle {
  key: string;
  year: number;
  make: string;
  model: string;
  label: string;
  /** Serialized form, used as the cookie value and React key. */
  id: string;
}

export const GARAGE_MAX = 3;
export const GARAGE_COOKIE_MAX_AGE = 60 * 60 * 24 * 30;

/** Validates "KEY|YEAR" against the index; anything unknown or out of range is dropped. */
export function parseVehicle(raw: string | undefined | null): Vehicle | null {
  if (!raw || raw.length > 80) return null;
  const m = /^([A-Z0-9-]{3,60})\|(\d{4})$/.exec(raw);
  if (!m) return null;
  const v = IDX.vehicles[m[1]!];
  const year = Number(m[2]);
  if (!v || year < v.years[0] || year > v.years[1]) return null;
  return { key: m[1]!, year, make: v.make, model: v.model, label: `${year} ${v.make} ${v.model}`, id: `${m[1]}|${year}` };
}

export function parseGarage(raw: string | undefined | null): Vehicle[] {
  const out: Vehicle[] = [];
  for (const part of (raw ?? "").split(",").slice(0, 10)) {
    const v = parseVehicle(part.trim());
    if (v && !out.some((x) => x.id === v.id)) out.push(v);
  }
  return out.slice(-GARAGE_MAX);
}

export const serializeGarage = (vs: Vehicle[]) => vs.map((v) => v.id).join(",");

/** Garage + active vehicle from cookies. The active vehicle must be in the garage. */
export async function getGarage(): Promise<{ vehicles: Vehicle[]; active: Vehicle | null }> {
  const jar = await cookies();
  const vehicles = parseGarage(jar.get(COOKIE.garage)?.value);
  const activeId = jar.get(COOKIE.garageActive)?.value;
  return { vehicles, active: vehicles.find((v) => v.id === activeId) ?? null };
}

/** Product IDs to show for a vehicle: parts that fit that model year, plus universal parts. */
export function allowedProductIds(v: Vehicle): string[] {
  return [...new Set([...(IDX.byVehicleYear[v.id] ?? []), ...IDX.universal])];
}

export type FitStatus = "fits" | "no-fit" | "universal" | "unknown";

export function fitStatus(productId: string, v: Vehicle | null): FitStatus {
  if (UNIVERSAL.has(productId)) return "universal";
  if (!IDX.byProduct[productId]) return "unknown";
  if (!v) return "unknown";
  return (IDX.byVehicleYear[v.id] ?? []).includes(productId) ? "fits" : "no-fit";
}

export const isUniversal = (productId: string) => UNIVERSAL.has(productId);

/** Fitment table rows (Make / Model / Years) for a product, sorted. */
export function fitmentRows(productId: string): { key: string; make: string; model: string; years: string }[] {
  return (IDX.byProduct[productId] ?? [])
    .map((key) => ({ key, v: IDX.vehicles[key] }))
    .filter((x): x is { key: string; v: FitmentIndex["vehicles"][string] } => !!x.v)
    .map(({ key, v }) => ({ key, make: v.make, model: v.model, years: `${v.years[0]}–${v.years[1]}` }))
    .sort((a, b) => a.make.localeCompare(b.make) || a.model.localeCompare(b.model) || a.years.localeCompare(b.years));
}

/** Dependent Make → Model → Year data for the selector (small; safe to send to the client). */
export interface VehicleTree {
  makes: { make: string; models: { model: string; key: string; years: number[] }[] }[];
}
export function vehicleTree(): VehicleTree {
  const makes = Object.keys(IDX.makes).sort();
  return {
    makes: makes.map((make) => ({
      make,
      models: Object.entries(IDX.vehicles)
        .filter(([, v]) => v.make === make)
        .map(([key, v]) => ({
          model: v.years[0] === v.years[1] ? v.model : `${v.model} (${v.years[0]}–${v.years[1]})`,
          key,
          years: Array.from({ length: v.years[1] - v.years[0] + 1 }, (_, i) => v.years[1] - i),
        }))
        .sort((a, b) => a.model.localeCompare(b.model)),
    })),
  };
}
